// Generated by Claude Sonnet 5. Not hand-written by the project author.
//
// Runs the official test/benchmark/*.lox scripts through both the Wasm
// LoxRunner and (if available) the native `cli` binary, and prints a
// comparison table.
//
// Env vars:
//   ROX_NATIVE_BINARY    path to the native release binary
//                         (default: rox/target/release/rox_cli --
//                          adjust if rox/cli/Cargo.toml's [package] name
//                          produces a different binary name)
//   ROX_BENCH_ITERATIONS timed iterations per benchmark (default: 10)
//   ROX_BENCH_WARMUP     untimed warmup iterations per benchmark (default: 2)

import path from 'node:path';
import { promises as fs } from 'node:fs';
import { discoverBenchmarks } from './discoverBenchmarks';
import { timeWasmRun } from './wasmTiming';
import { timeNativeRun } from './nativeTiming';
import { printBenchmarkReport } from './report';
import { BenchmarkResult } from './types';

const BENCHMARK_ROOT = path.resolve(__dirname, '../../../mothership/test/benchmark');
const NATIVE_BINARY =
  process.env.ROX_NATIVE_BINARY ?? path.resolve(__dirname, '../../../target/release/rox');
const ITERATIONS = 1; // Number(process.env.ROX_BENCH_ITERATIONS ?? 10);
const WARMUP = 0; // Number(process.env.ROX_BENCH_WARMUP ?? 2);

async function nativeBinaryExists(): Promise<boolean> {
  try {
    await fs.access(NATIVE_BINARY);
    return true;
  } catch {
    return false;
  }
}

function parseReportedSeconds(output: string | null): number | null {
  if (!output) return null;
  const lines = output.trim().split('\n');
  const last = lines[lines.length - 1];
  const value = Number(last);
  return Number.isFinite(value) ? value : null;
}

async function main(): Promise<void> {
  const files = (await discoverBenchmarks(BENCHMARK_ROOT));
  console.log(`Discovered ${files.length} benchmark files under ${BENCHMARK_ROOT}`);

  const hasNative = await nativeBinaryExists();
  if (!hasNative) {
    console.log(
      `Native binary not found at ${NATIVE_BINARY} -- build it with "cargo build --release" ` +
        `(adjust ROX_NATIVE_BINARY if your cli crate produces a different binary name). ` +
        `Continuing with Wasm-only timings.`
    );
  }
  console.log('');

  const results: BenchmarkResult[] = [];

  for (const filePath of files) {
    const name = path.basename(filePath, '.lox');
    const source = await fs.readFile(filePath, 'utf8');

    const wasmTimingsMs: number[] = [];
    let lastWasmOutput: string | null = null;
    for (let i = 0; i < WARMUP + ITERATIONS; i++) {
      const { ms, output, error } = timeWasmRun(source);
      if (error) {
        console.error(`${name}: wasm run failed, skipping -- ${error}`);
        break;
      }
      lastWasmOutput = (output ?? []).join("\n");
      if (i >= WARMUP) wasmTimingsMs.push(ms);
    }

    let nativeTimingsMs: number[] | null = null;
    if (hasNative) {
      nativeTimingsMs = [];
      for (let i = 0; i < WARMUP + ITERATIONS; i++) {
        const { ms, stderr, exitCode } = timeNativeRun(NATIVE_BINARY, filePath);
        if (exitCode !== 0) {
          console.error(`${name}: native run failed (exit ${exitCode}), skipping native timings -- ${stderr}`);
          nativeTimingsMs = null;
          break;
        }
        if (i >= WARMUP) nativeTimingsMs.push(ms);
      }
    }

    results.push({
      name,
      path: filePath,
      wasmTimingsMs,
      nativeTimingsMs,
      reportedVmSeconds: parseReportedSeconds(lastWasmOutput),
    });
  }

  console.log('');
  printBenchmarkReport(results);
}

main().catch((err) => {
  console.error(err);
  process.exitCode = 1;
});
